namespace CSharpPracticum.Tasks.Level2;
internal class Task18_TryParse:ITask {public string Title=>"Задание 18: TryParse vs try/catch";public string Description=>"Сравнить обработку корректного и некорректного числового ввода.";public string[] Requirements=>new[]{"int.TryParse с bool и out.","int.Parse внутри try/catch FormatException.","Оба способа показать на корректном и некорректном вводе."};public void Run(){foreach(string s in new[]{"123","abc"}){Console.WriteLine($"Ввод: {s}");Console.WriteLine(Try(s,out int a)?$"TryParse: {a}":"TryParse: ошибка");int? b=Parse(s);Console.WriteLine(b.HasValue?$"Parse: {b.Value}":"Parse: ошибка");}}private static bool Try(string s,out int value)=>int.TryParse(s,out value);private static int? Parse(string s){try{return int.Parse(s);}catch(FormatException){return null;}}}
